      if (tab === "atamalar") body = '<div class="card"><div class="card-head"><h3>Güzergâh atamaları</h3><div class="right"><button class="btn btn-primary btn-sm" data-act="mg-new" data-k="atamalar">' + ic("plus", 15) + "Atama ekle</button></div></div>" + U.table(MGMT.atamalar.cols.slice(1), asg) + "</div>";
